// Filter merged RSS items to UK cost-of-living news and shape them for FinTime.
const body = ($('Webhook').first().json.body) || {};
const requestedTopic = typeof body.topic === 'string' ? body.topic.trim().toLowerCase().slice(0, 60) : '';
const limit = Math.max(1, Math.min(parseInt(body.limit, 10) || 6, 10));

const TOPICS = {
  'energy': ['energy', 'price cap', 'ofgem', 'gas bill', 'electricity', 'energy bill'],
  'fuel': ['fuel', 'petrol', 'diesel'],
  'interest rates': ['interest rate', 'interest rates', 'bank rate', 'base rate', 'mortgage', 'mortgages'],
  'inflation': ['inflation', 'cpi', 'food prices', 'cost of living', 'cost-of-living'],
  'wages': ['wages', 'wage', 'minimum wage', 'living wage', 'pay rise'],
  'benefits': ['benefits', 'universal credit', 'state pension', 'dwp'],
  'housing': ['rent', 'rents', 'renters', 'landlord'],
  'tax': ['council tax', 'budget', 'tax', 'taxes', 'income tax', 'national insurance'],
};
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const has = (text, words) => words.some((w) => new RegExp('\\b' + esc(w) + '\\b', 'i').test(text));
const classify = (text) => Object.keys(TOPICS).find((t) => has(text, TOPICS[t])) || null;
const clean = (v, max) => {
  let s = String(v || '').replace(/<[^>]*>/g, ' ').replace(/[\u0000-\u001f\u007f-\u009f]/g, ' ').replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
};
const publisherOf = (link) => {
  const host = (String(link || '').match(/^https?:\/\/([^/]+)/i) || [])[1] || '';
  if (host.includes('bbc.')) return 'BBC News';
  if (host.includes('theguardian.')) return 'The Guardian';
  if (host.includes('bankofengland.')) return 'Bank of England';
  return host.replace(/^www\./, '');
};

let topicWords = [];
if (requestedTopic) {
  const key = Object.keys(TOPICS).find((t) => t === requestedTopic || TOPICS[t].includes(requestedTopic) || t.startsWith(requestedTopic));
  topicWords = key ? [key, ...TOPICS[key]] : requestedTopic.split(/[^a-z0-9]+/).filter((w) => w.length > 2);
}

const seen = new Set();
const items = [];
for (const { json } of $input.all()) {
  if (!json || json.error || !json.title) continue;
  const title = clean(json.title, 200);
  const summary = clean(json.contentSnippet || json.content || json.description || json.summary, 240);
  const text = title + ' ' + summary;
  const topic = classify(text);
  if (!topic) continue;
  const url = /^https?:\/\//i.test(json.link || '') ? json.link : '';
  const key = (url || title).toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  const date = new Date(json.isoDate || json.pubDate || 0);
  items.push({
    title,
    summary,
    url,
    published: isNaN(date) || date.getTime() === 0 ? '' : date.toISOString(),
    publisher: publisherOf(url),
    topic,
    _match: topicWords.length ? has(text + ' ' + topic, topicWords) : false,
  });
}

items.sort((a, b) => (b._match - a._match) || b.published.localeCompare(a.published));
return [{ json: { items: items.slice(0, limit).map(({ _match, ...rest }) => rest) } }];
